# First, let's see what's the maximum edges possible with girth >= 7
# Let's try a heuristic: start with a random graph and try to add edges

def random_graph_with_girth(n, target_edges, min_girth, max_attempts=10000):
    best_edges = 0
    best_graph = []

    for attempt in range(max_attempts):
        # Start with empty graph
        edges = []
        adj = [[] for _ in range(n)]

        # Try to add edges randomly
        all_possible = [(i, j) for i in range(n) for j in range(i+1, n)]
        random.shuffle(all_possible)

        for u, v in all_possible:
            # Check if adding this edge creates a cycle of length < min_girth
            # We need to check if there's a path of length < min_girth-1 between u and v
            # BFS limited depth
            dist = [-1] * n
            dist[u] = 0
            q = deque([u])
            found_short = False
            while q:
                x = q.popleft()
                if dist[x] >= min_girth - 2:
                    break
                for w in adj[x]:
                    if dist[w] == -1:
                        dist[w] = dist[x] + 1
                        if w == v:
                            found_short = True
                            break
                        q.append(w)
                if found_short:
                    break

            if not found_short:
                edges.append((u, v))
                adj[u].append(v)
                adj[v].append(u)
                if len(edges) >= target_edges:
                    break

        if len(edges) > best_edges:
            best_edges = len(edges)
            best_graph = edges[:]
            print(f"Attempt {attempt}: {len(edges)} edges")
            if len(edges) >= target_edges:
                # Check girth
                g = girth(edges, n)
                print(f"Girth: {g}")
                if g >= min_girth:
                    return edges

    return best_graph

